    };

init();

var R=null,_scheme='',_data=null,_perf=null,_org=null,_ovl=null,_pan=null,_stk=[];
var _filters={};
(function(){var n=new Date(),y=n.getFullYear(),m=String(n.getMonth()+1).padStart(2,'0'),d=String(n.getDate()).padStart(2,'0');_filters.date_from=y+'-'+m+'-01';_filters.date_to=y+'-'+m+'-'+d;})();
var BUCKET_COLORS={unvisited:'#6b7280',docs_in_progress:'#f59e0b',docs_ready:'#8b5cf6',applied_pending:'#3b82f6',goal:'#22c55e',negative:'#ef4444'};
var BUCKET_LABELS={unvisited:'Unvisited',docs_in_progress:'Docs In Progress',docs_ready:'Docs Ready',applied_pending:'Applied – Pending',goal:'Goal Achieved',negative:'Closed – Negative'};

function api(m,a){return new Promise(function(res,rej){var t=setTimeout(function(){rej(new Error('timeout'));},25000);frappe.call({method:m,args:a,callback:function(r){clearTimeout(t);res(r.message);},error:function(e){clearTimeout(t);rej(e);}});});}
function fmt(n){if(n==null)return '—';return Number(n).toLocaleString();}
function pct(n){if(n==null)return '';return Number(n).toFixed(1)+'%';}
function esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

async function init(){
  R=root_element.querySelector('#ent-root');
  _scheme=localStorage.getItem('ent_scheme_'+frappe.session.user)||'';
  try{
    var schemes=await api('changemakers.generic_dashboard_api.get_dashboard_schemes',{});
    if(!schemes||!schemes.schemes||!schemes.schemes.length){R.innerHTML='<div class="ent-loading">No active schemes found.</div>';return;}
    if(!_scheme||!schemes.schemes.find(function(s){return s.entitlement_code===_scheme;}))
      _scheme=schemes.schemes[0].entitlement_code;
    renderScope(schemes.schemes);
    await loadData();
  }catch(e){R.innerHTML='<div class="ent-loading" style="color:red">Error: '+esc(e&&e.message||String(e))+'</div>';}
}

function renderScope(schemes){
  var opts=schemes.map(function(s){return '<option value="'+esc(s.entitlement_code)+'"'+(s.entitlement_code===_scheme?' selected':'')+'>'+esc(s.entitlement_name)+'</option>';}).join('');
  var di='font-size:12px;padding:3px 6px;border:1px solid var(--border-color);border-radius:4px;background:var(--bg-color,#fff);color:var(--text-color,#111)';
  var scope='<div class="ent-scope">'
    +'<label>Scheme:</label><select id="ent-sel">'+opts+'</select>'
    +'<label>Org</label><select id="ent-f-org" style="'+di+'"><option value="">All</option></select>'
    +'<label>IU</label><select id="ent-f-iu" style="'+di+'"><option value="">All</option></select>'
    +'<label>Street</label><select id="ent-f-st" style="'+di+'"><option value="">All</option></select>'
    +'<label>From</label><input type="date" id="ent-f-from" value="'+_filters.date_from+'" style="'+di+'">'
    +'<label>To</label><input type="date" id="ent-f-to" value="'+_filters.date_to+'" style="'+di+'">'
    +'<button onclick="entApply()">Apply</button>'
    +'</div>';
  R.innerHTML=scope+'<div id="ent-body"><div class="ent-loading"><span class="spinner-border spinner-border-sm"></span> Loading…</div></div>';
  var sel=R.querySelector('#ent-sel');
  if(sel)sel.onchange=function(){_scheme=sel.value;localStorage.setItem('ent_scheme_'+frappe.session.user,_scheme);};
  populateScopeOptions();
}

function _scopeList(doctype,opts){return frappe.db.get_list(doctype,opts);}
function _fillSel(id,items,field,cur){
  var el=R&&R.querySelector('#'+id);if(!el)return;
  el.innerHTML='<option value="">All</option>'+items.filter(function(r){return r[field];}).map(function(r){return '<option'+(r[field]===cur?' selected':'')+' value="'+esc(r[field])+'">'+esc(r[field])+'</option>';}).join('');
}
function populateScopeOptions(){
  var curOrg=_filters.implementing_org||'';
  var curIU=_filters.intervention_unit||'';
  var curSt=_filters.street||'';
  var iuOpts={fields:['intervention_units'],group_by:'intervention_units',limit:500};
  if(curOrg)iuOpts.filters=[['implementing_org','=',curOrg]];
  var stOpts={fields:['name'],limit:1000};
  if(curIU)stOpts.filters=[['intervention_units','=',curIU]];
  else if(curOrg)stOpts.filters=[['implementing_org','=',curOrg]];
  Promise.all([
    _scopeList('Street List  - WRP',{fields:['implementing_org'],group_by:'implementing_org',limit:200}),
    _scopeList('Street List  - WRP',iuOpts),
    _scopeList('Street List  - WRP',stOpts)
  ]).then(function(results){
    _fillSel('ent-f-org',results[0],'implementing_org',curOrg);
    _fillSel('ent-f-iu',results[1],'intervention_units',curIU);
    _fillSel('ent-f-st',results[2],'name',curSt);
    _attachScopeCascade();
  }).catch(function(){});
}
function _attachScopeCascade(){
  var orgEl=R&&R.querySelector('#ent-f-org');
  var iuEl=R&&R.querySelector('#ent-f-iu');
  var stEl=R&&R.querySelector('#ent-f-st');
  if(orgEl)orgEl.onchange=function(){
    var org=orgEl.value;
    var io={fields:['intervention_units'],group_by:'intervention_units',limit:500};
    var so={fields:['name'],limit:1000};
    if(org){io.filters=[['implementing_org','=',org]];so.filters=[['implementing_org','=',org]];}
    Promise.all([_scopeList('Street List  - WRP',io),_scopeList('Street List  - WRP',so)]).then(function(r){
      _fillSel('ent-f-iu',r[0],'intervention_units','');
      _fillSel('ent-f-st',r[1],'name','');
    });
  };
  if(iuEl)iuEl.onchange=function(){
    var iu=iuEl.value,org=orgEl&&orgEl.value;
    var so={fields:['name'],limit:1000};
    if(iu)so.filters=[['intervention_units','=',iu]];
    else if(org)so.filters=[['implementing_org','=',org]];
    _scopeList('Street List  - WRP',so).then(function(items){_fillSel('ent-f-st',items,'name','');});
  };
}

async function loadData(){
  var body=R.querySelector('#ent-body');
  if(body)body.innerHTML='<div class="ent-loading"><span class="spinner-border spinner-border-sm"></span> Loading…</div>';
  var results=await Promise.all([
    api('changemakers.generic_dashboard_api.get_programme_overview',{entitlement_code:_scheme,implementing_org:_filters.implementing_org||'',intervention_unit:_filters.intervention_unit||'',street:_filters.street||'',date_from:_filters.date_from||'',date_to:_filters.date_to||''}),
    api('changemakers.generic_dashboard_api.get_co_performance_table',{entitlement_code:_scheme,implementing_org:_filters.implementing_org||'',intervention_unit:_filters.intervention_unit||'',street:_filters.street||'',date_from:_filters.date_from||'',date_to:_filters.date_to||''}),
    api('changemakers.generic_dashboard_api.get_org_progress_table',{entitlement_code:_scheme,implementing_org:_filters.implementing_org||'',intervention_unit:_filters.intervention_unit||'',street:_filters.street||''}),
  ]);
  _data=results[0];_perf=results[1];_org=results[2];
  renderDashboard();
  buildPanel();
}

window.entApply=function(){
  var sel=R&&R.querySelector('#ent-sel');
  var org=R&&R.querySelector('#ent-f-org');
  var iu=R&&R.querySelector('#ent-f-iu');
  var st=R&&R.querySelector('#ent-f-st');
  var from=R&&R.querySelector('#ent-f-from');
  var to=R&&R.querySelector('#ent-f-to');
  if(sel&&sel.value)_scheme=sel.value;
  _filters={};
  if(org&&org.value)_filters.implementing_org=org.value;
  if(iu&&iu.value)_filters.intervention_unit=iu.value;
  if(st&&st.value)_filters.street=st.value;
  if(from&&from.value)_filters.date_from=from.value;
  if(to&&to.value)_filters.date_to=to.value;
  localStorage.setItem('ent_scheme_'+frappe.session.user,_scheme);
  loadData();
};
window.entRefresh=window.entApply;


function renderOrgTable(){
  if(!_org||!_org.rows||!_org.rows.length)return '';
  var goalLabel=esc(_org.goal_label||'Goal');
  var hdr='<div class="ent-sec">Implementing Org Progress</div>'
    +'<div style="overflow-x:auto"><table class="ent-tbl">'
    +'<thead><tr>'
    +'<th>Organisation</th><th>Total</th><th>Unvisited</th><th>In Progress</th><th>Docs Ready</th><th>Applied</th><th>'+goalLabel+'</th><th>Closed</th><th>'+goalLabel+' %</th>'
    +'</tr></thead><tbody>';
  var rows=_org.rows;
  var totTotal=0,totUnv=0,totDip=0,totDr=0,totApp=0,totGoal=0,totNeg=0;
  var body='';
  for(var i=0;i<rows.length;i++){
    var r=rows[i];
    totTotal+=r.total||0;totUnv+=r.unvisited||0;totDip+=r.docs_in_progress||0;
    totDr+=r.docs_ready||0;totApp+=r.applied_pending||0;totGoal+=r.goal||0;totNeg+=r.negative||0;
    var satCol=r.saturation_pct>=50?'var(--g)':r.saturation_pct>=25?'var(--o)':'var(--r)';
    body+='<tr>'
      +'<td style="font-weight:500">'+esc(r.org)+'</td>'
      +'<td>'+fmt(r.total)+'</td>'
      +'<td style="color:var(--text-muted)">'+fmt(r.unvisited)+'</td>'
      +'<td style="color:#f59e0b">'+fmt(r.docs_in_progress)+'</td>'
      +'<td style="color:#8b5cf6">'+fmt(r.docs_ready)+'</td>'
      +'<td style="color:#3b82f6">'+fmt(r.applied_pending)+'</td>'
      +'<td style="color:var(--g);font-weight:600">'+fmt(r.goal)+'</td>'
      +'<td style="color:var(--r)">'+fmt(r.negative)+'</td>'
      +'<td><span style="color:'+satCol+';font-weight:600">'+pct(r.saturation_pct)+'</span></td>'
      +'</tr>';
  }
  var totPct=totTotal?((totGoal/totTotal)*100).toFixed(1)+'%':'0%';
  var totSatPct=totTotal?(totGoal/totTotal*100):0;
  var totSatCol=totSatPct>=50?'var(--g)':totSatPct>=25?'var(--o)':'var(--r)';
  var footer='<tr style="font-weight:700;border-top:2px solid var(--border-color,#e5e7eb)">'
    +'<td>Total</td>'
    +'<td>'+fmt(totTotal)+'</td>'
    +'<td>'+fmt(totUnv)+'</td>'
    +'<td>'+fmt(totDip)+'</td>'
    +'<td>'+fmt(totDr)+'</td>'
    +'<td>'+fmt(totApp)+'</td>'
    +'<td style="color:var(--g)">'+fmt(totGoal)+'</td>'
    +'<td>'+fmt(totNeg)+'</td>'
    +'<td><span style="color:'+totSatCol+'">'+totPct+'</span></td>'
    +'</tr>';
  return hdr+body+footer+'</tbody></table></div>';
}

function renderDashboard(){
  if(!_data){return;}
  var total=_data.total||1;
  var cards='<div class="ent-sec">Overview — '+esc(_data.entitlement_name)+'</div><div class="ent-row">'
    +'<div class="ent-card"><div class="ent-val">'+fmt(_data.total)+'</div><div class="ent-lbl">Total Beneficiaries</div></div>'
    +'<div class="ent-card"><div class="ent-val" style="color:var(--b)">'+fmt(_data.visited)+'</div><div class="ent-lbl">Visited ('+pct(_data.coverage_pct)+')</div></div>'
    +'<div class="ent-card"><div class="ent-val" style="color:var(--g)">'+fmt(_data.goal_count)+'</div><div class="ent-lbl">'+esc(_data.final_status_label||'Goal')+' ('+pct(_data.saturation_pct)+')</div></div>'
    +'<div class="ent-card click" onclick="entDrillAlert(\'sla\')"><div class="ent-val" style="color:var(--r)">'+fmt(_data.sla_overdue_count)+'</div><div class="ent-lbl">SLA Overdue</div></div>'
    +'<div class="ent-card click" onclick="entDrillAlert(\'ac_review\')"><div class="ent-val" style="color:var(--o)">'+fmt(_data.pending_ac_reviews)+'</div><div class="ent-lbl">Pending AC Reviews</div></div>'
